function tokenize(text) {
  var normalized = normalize(text);
  var tokens = [];
  var current = '';
  for (var i = 0; i < normalized.length; i++) {
    var ch = normalized[i];
    if (isAsciiAlphanumeric(ch)) {
      current += ch;
    } else if (ch === "'") {
      // apostrophe acts as separator: flush current, then reset
      if (current.length > 0) {
        tokens.push(current);
        current = '';
      }
    } else {
      // any other character (including accented letters after normalization) is a separator
      if (current.length > 0) {
        tokens.push(current);
        current = '';
      }
    }
  }
  if (current.length > 0) {
    tokens.push(current);
  }
  // stopwords list is empty per specification, so no filtering needed
  return tokens;
}

function isAsciiAlphanumeric(ch) {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9');
}

